#!/usr/bin/env bash
# Generated by aibox — do not edit manually.
# Codex legacy `notify` adapter. Codex appends one JSON payload argument.
set -u

delegate_json=""
if [[ "${1:-}" == --delegate-json ]]; then
    [[ $# -ge 3 ]] || exit 0
    delegate_json="$2"
    shift 2
fi
payload="${1:-}"
[[ -n "$payload" ]] || payload="{}"

state="$(python3 -c '
import json, sys
try:
    event = json.loads(sys.argv[1])
except (ValueError, TypeError):
    raise SystemExit(0)
if event.get("type") != "agent-turn-complete":
    raise SystemExit(0)
message = event.get("last-assistant-message") or event.get("last_assistant_message") or ""
print("question" if str(message).rstrip().endswith(("?", "？")) else "done", end="")
' "$payload" 2>/dev/null || true)"

if [[ -n "$state" ]]; then
    printf '%s' "$payload" \
        | aibox-agent-signal "$state" --harness codex --hook-input >/dev/null 2>&1 \
        || true
fi

# A project-local notify command may predate aibox. Keep it as a delegate and
# pass Codex's original payload through unchanged.
if [[ -n "$delegate_json" ]]; then
    python3 -c '
import json, subprocess, sys
try:
    command = json.loads(sys.argv[1])
except (ValueError, TypeError):
    raise SystemExit(0)
if isinstance(command, list) and command and all(isinstance(item, str) for item in command):
    subprocess.run(command + [sys.argv[2]], check=False)
' "$delegate_json" "$payload" >/dev/null 2>&1 || true
fi
